#!/usr/bin/env node
// Helpers shared by scripts/check-contract-drift.sh and scripts/sync-contracts.sh. Plain Node so the
// behaviour is identical on GNU and BSD systems (no sed -i, no line-count assumptions).
//
//   rewrite <dir>            add ".js" to relative import specifiers of every .js file under <dir>
//   closure <root> <entry>   print the files (relative to <root>, sorted) reachable from <entry> through
//                            relative imports, <entry> included; exits 1 if an import does not resolve
//   body <file>              print <file> from its "// Code generated by" line on (drops any vendoring header)
import fs from 'node:fs';
import path from 'node:path';

const SPECIFIER = /\bfrom\s+"(\.\.?\/[^"]+)"/g;
const GENERATED_MARKER = /^\/\/ Code generated by /;

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    return e.isDirectory() ? walk(p) : [p];
  });
}

function rewrite(dir) {
  for (const file of walk(dir).filter((f) => f.endsWith('.js'))) {
    const text = fs.readFileSync(file, 'utf8');
    const next = text.replace(/\bfrom\s+"(\.\.?\/[^"]+)"/g, (_m, spec) => `from "${spec}.js"`);
    if (next !== text) fs.writeFileSync(file, next);
  }
}

function closure(root, entry) {
  const seen = new Set();
  const missing = [];
  const queue = [path.resolve(root, entry)];
  while (queue.length) {
    const file = queue.pop();
    if (seen.has(file)) continue;
    seen.add(file);
    if (!fs.existsSync(file)) {
      missing.push(path.relative(root, file));
      continue;
    }
    for (const m of fs.readFileSync(file, 'utf8').matchAll(SPECIFIER)) {
      queue.push(path.resolve(path.dirname(file), m[1]));
    }
  }
  if (missing.length) {
    console.error(`unresolved relative imports: ${missing.sort().join(', ')}`);
    process.exit(1);
  }
  return [...seen].map((f) => path.relative(root, f)).sort();
}

function body(file) {
  const lines = fs.readFileSync(file, 'utf8').split('\n');
  const start = lines.findIndex((l) => GENERATED_MARKER.test(l));
  if (start < 0) {
    console.error(`${file}: no "// Code generated by" line; not a generated binding`);
    process.exit(1);
  }
  process.stdout.write(lines.slice(start).join('\n'));
}

const [cmd, a, b] = process.argv.slice(2);
if (cmd === 'rewrite' && a) rewrite(a);
else if (cmd === 'closure' && a && b) process.stdout.write(closure(a, b).map((f) => `${f}\n`).join(''));
else if (cmd === 'body' && a) body(a);
else {
  console.error('usage: contracts-tools.mjs rewrite <dir> | closure <root> <entry> | body <file>');
  process.exit(2);
}
